/*
 * A231711  Numbers n such that n > sigma(n) - sigma(n-1).
 * https://oeis.org/A231711
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth positive integer n such that * n > sigma(n) -
 *            sigma(n-1), * where sigma(m) is the sum of all positive divisors
 *            of m. * The sequence is generated by testing each integer in
 *            order * and keeping the ones that satisfy the condition
 * Range:     u8 n <= 97, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>

/* ----------------------------------------------------------- */
/*  Sum of divisors of a number (sigma function) for idx_t n.  */
/* ----------------------------------------------------------- */
static seq_t sigma_of(idx_t n)
{
    seq_t sum = 0;
    for (idx_t i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            sum += (seq_t)i;
            idx_t j = n / i;
            if (j != i) {
                sum += (seq_t)j;
            }
        }
    }
    return sum;
}

/* ----------------------------------------------------------- */
/*  Global state for the sequence values.                     */
/* ----------------------------------------------------------- */
static seq_t *seq_vals = NULL;
static size_t seq_cap = 0;     /* allocated capacity          */
static size_t seq_len = 0;     /* number of stored sequence  */
static idx_t last_checked = 2; /* last number tested (start < first term) */

/* ----------------------------------------------------------- */
/*  Ensure that the first 'need' terms of the sequence are   */
/*  computed and stored in 'seq_vals'.                        */
/* ----------------------------------------------------------- */
static void ensure_seq(size_t need)
{
    while (seq_len < need) {
        ++last_checked;                           /* next integer to test */
        seq_t sigma_n   = sigma_of(last_checked);     /* sigma(n)   */
        seq_t sigma_prev= sigma_of(last_checked - 1); /* sigma(n-1) */

        /* Add this integer to the sequence if it satisfies the condition. */
        if (sigma_n <= sigma_prev ||
            (seq_t)last_checked > sigma_n - sigma_prev) {

            /* Grow the array if necessary. */
            if (seq_len == seq_cap) {
                size_t new_cap = seq_cap ? seq_cap * 2 : 16;
                seq_t *new_arr = (seq_t*)malloc(new_cap * sizeof(seq_t));
                if (!new_arr) {
                    /* In a real program you might handle the error. */
                    exit(1);
                }
                if (seq_vals) {
                    for (size_t i = 0; i < seq_len; ++i)
                        new_arr[i] = seq_vals[i];
                    free(seq_vals);
                }
                seq_vals = new_arr;
                seq_cap  = new_cap;
            }
            seq_vals[seq_len++] = (seq_t)last_checked;
        }
    }
}

/* ----------------------------------------------------------- */
/*  Public sequence function: gives the nth element of A231711 */
/* ----------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined, but safe */
    ensure_seq((size_t)n);
    return seq_vals[n - 1];        /* zero‑based indexing */
}
